                )}
                <button onClick={async () => {
                  await api(`/api/providers/${p.id}/disconnect`, { method: 'POST' });
                  reload();
                }} style={{
                  width: '100%', padding: '8px 16px', fontSize: 13, borderRadius: 4,
                  border: '1px solid rgba(217,119,87,0.3)', color: '#D97757',
                  background: 'transparent', cursor: 'pointer',
                }}>
                  {t('providers.disconnect')}
                </button>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

/**
 * Chatty — First-login setup wizard.
 *
 * Walks user through AI provider setup and branding configuration.
 * Each step can be skipped; the entire wizard can be dismissed.
 */

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { api } from '../core/api/client';
import { toast } from '../shared/toast';
import { ProviderSetup } from './ProviderSetup';
import type { BrandingConfig } from '../core/types';

type Step = 'welcome' | 'providers' | 'branding';

const STEPS: Step[] = ['welcome', 'providers', 'branding'];

export function SetupWizard() {
  const { t } = useTranslation();
  const [step, setStep] = useState<Step>('welcome');
  const navigate = useNavigate();

  // Branding state
  const [companyName, setCompanyName] = useState('');
  const [accentColor, setAccentColor] = useState('#393c74');
  const [logoUploaded, setLogoUploaded] = useState(false);
  const [saving, setSaving] = useState(false);

  const stepIndex = STEPS.indexOf(step);

  function nextStep() {
    if (stepIndex < STEPS.length - 1) {
      setStep(STEPS[stepIndex + 1]);
    }
  }

  async function finish() {
    try {
      await api('/api/setup/complete', { method: 'POST' });
    } catch { /* navigate regardless */ }
    navigate('/');
  }

  async function skipAll() {
    try {
      await api('/api/setup/skip', { method: 'POST' });
    } catch { /* navigate regardless */ }
    navigate('/');
  }

  async function saveBranding() {
    setSaving(true);
    try {
      const body: Record<string, string> = {};
      if (companyName.trim()) body.company_name = companyName.trim();
      if (accentColor) body.accent_color = accentColor;

      if (Object.keys(body).length > 0) {
        const updated = await api<BrandingConfig>('/api/branding', {
          method: 'PUT',
          body: JSON.stringify(body),
        });
        document.documentElement.style.setProperty('--brand-color', updated.accent_color);
      }

      await finish();
    } catch {
      toast.error(t('setupWizard.errors.finishFailed'));
    } finally {
      setSaving(false);
    }
  }

  async function uploadLogo(file: File) {
    const form = new FormData();
    form.append('file', file);

    const res = await fetch('/api/branding/logo', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${sessionStorage.getItem('chatty_token')}`,
      },
      body: form,
    });

    if (res.ok) setLogoUploaded(true);
  }

  return (
    <div className="min-h-screen bg-ch-bg flex items-center justify-center p-6">
      <div className="w-full max-w-lg">
        {/* Step indicators */}
        <div className="flex items-center justify-center gap-2 mb-8">
          {STEPS.map((s, i) => (
            <div
              key={s}
              className={`h-1.5 rounded-full transition-all ${
                i <= stepIndex ? 'bg-brand w-10' : 'bg-ch-bg-raised w-6'
              }`}
            />
          ))}
        </div>

        <div className="bg-ch-bg-elev border border-ch-line rounded-md p-8">
          {/* Welcome */}
          {step === 'welcome' && (
            <div className="text-center space-y-6">
              <div className="text-5xl">&#x1f680;</div>

              <h1 className="text-2xl font-bold text-white">
                {t('setupWizard.welcome.title')}
              </h1>

              <p className="text-ch-ink-mute">
                {t('setupWizard.welcome.description')}
              </p>

              <div className="space-y-3 pt-2">
                <button
                  onClick={nextStep}
                  className="w-full py-3 bg-brand text-white font-semibold rounded-md hover:opacity-90 transition"
                >
                  {t('setupWizard.welcome.getStarted')}
                </button>

                <button
                  onClick={skipAll}
                  className="w-full py-3 text-ch-ink-mute hover:text-white text-sm transition"
                >
                  {t('setupWizard.welcome.skipSetup')}
                </button>
              </div>
            </div>
          )}

          {/* AI Providers */}
          {step === 'providers' && (
            <div className="space-y-6">
              <div>
                <h2 className="text-xl font-bold text-white">
                  {t('setupWizard.providers.title')}
                </h2>

                <p className="text-ch-ink-mute text-sm mt-1">
                  {t('setupWizard.providers.description')}
                </p>
              </div>

              <ProviderSetup />

              <div className="flex gap-3 pt-2">
                <button
                  onClick={nextStep}
                  className="flex-1 py-3 bg-brand text-white font-semibold rounded-md hover:opacity-90 transition"
                >
                  {t('setupWizard.providers.continue')}
                </button>

                <button
                  onClick={nextStep}
                  className="py-3 px-5 text-ch-ink-mute hover:text-white text-sm rounded-md hover:bg-ch-bg-raised transition"
                >
                  {t('setupWizard.providers.skip')}
                </button>
              </div>
            </div>
          )}

          {/* Branding */}
          {step === 'branding' && (
            <div className="space-y-6">
              <div>
                <h2 className="text-xl font-bold text-white">
                  {t('setupWizard.branding.title')}
                </h2>

                <p className="text-ch-ink-mute text-sm mt-1">
                  {t('setupWizard.branding.description')}
                </p>
              </div>

              <div>
                <label className="block text-sm text-ch-ink-mute mb-2">
                  {t('setupWizard.branding.platformName')}
                </label>

                <input
                  value={companyName}
                  onChange={e => setCompanyName(e.target.value)}
                  placeholder={t('setupWizard.branding.platformNamePlaceholder')}
                  className="w-full bg-ch-bg-raised border border-ch-line-strong text-white rounded-lg px-4 py-3 focus:outline-none focus:border-brand placeholder-gray-500"
                />
              </div>

              <div>
                <label className="block text-sm text-ch-ink-mute mb-2">
                  {t('setupWizard.branding.accentColor')}
                </label>

                <div className="flex items-center gap-3">
                  <input
                    type="color"
                    value={accentColor}
                    onChange={e => setAccentColor(e.target.value)}
                    className="w-12 h-12 rounded-lg border-0 cursor-pointer bg-transparent"
                  />

                  <span className="text-ch-ink-mute font-mono text-sm">
                    {accentColor}
                  </span>
                </div>
              </div>

              <div>
                <label className="block text-sm text-ch-ink-mute mb-2">
                  {t('setupWizard.branding.logo')}
                </label>

                {logoUploaded && (
                  <p className="text-green-400 text-sm mb-2">
                    {t('setupWizard.branding.logoUploaded')}
                  </p>
                )}

                <input
                  type="file"
                  accept="image/png,image/jpeg,image/gif,image/webp,image/svg+xml"
                  onChange={e => {
                    const file = e.target.files?.[0];
                    if (file) uploadLogo(file).catch(console.error);
                  }}
                  className="text-sm text-ch-ink-mute"
                />
              </div>

              <div className="flex gap-3 pt-2">
                <button
                  onClick={saveBranding}
                  disabled={saving}
                  className="flex-1 py-3 bg-brand text-white font-semibold rounded-md hover:opacity-90 transition disabled:opacity-50"
                >
                  {saving
                    ? t('setupWizard.branding.saving')
                    : t('setupWizard.branding.finishSetup')}
                </button>

                <button
                  onClick={skipAll}
                  className="py-3 px-5 text-ch-ink-mute hover:text-white text-sm rounded-md hover:bg-ch-bg-raised transition"
                >
                  {t('setupWizard.branding.skip')}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { api } from '../core/api/client';

interface Props {
  provider: string;
  currentModel: string;
  onChanged: () => void;
}

export function ModelSelector({ provider, currentModel, onChanged }: Props) {
  const { t } = useTranslation();

  const [models, setModels] = useState<string[]>([]);
  const [selected, setSelected] = useState(currentModel);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    api<{ models: string[] }>(`/api/providers/${provider}/models`)
      .then(data => setModels(data.models))
      .catch(console.error);
  }, [provider]);

  async function save(model: string) {
    setSaving(true);
    try {
      await api('/api/providers/active', {
        method: 'PUT',
        body: JSON.stringify({ provider, model }),
      });
      setSelected(model);
      onChanged();
    } catch (err) {
      console.error('Failed to set model:', err);
    } finally {
      setSaving(false);
    }
  }

  if (!models.length) return null;

  return (
    <div>
      <label style={{
        display: 'block',
        fontFamily: "'JetBrains Mono', ui-monospace, monospace",
        fontSize: 9, letterSpacing: '0.16em', textTransform: 'uppercase',
        color: 'rgba(237,240,244,0.38)', marginBottom: 6,
      }}>
        {t('providers.model')}
      </label>
      <select
        value={selected}
        onChange={e => save(e.target.value)}
        disabled={saving}
        style={{
          width: '100%', boxSizing: 'border-box',
          background: 'rgba(34,40,48,0.55)', border: '1px solid rgba(230,235,242,0.14)',
          color: '#EDF0F4', borderRadius: 4, padding: '8px 12px', fontSize: 13,
          outline: 'none', opacity: saving ? 0.5 : 1,
        }}
      >
        {models.map(m => (
          <option key={m} value={m}>{m}</option>
        ))}
      </select>
    </div>
  );
}

"""
Chatty — Shared agent router factory.

Creates a FastAPI router with chat + context + conversation endpoints.
Used by the multi-agent system (agents/router.py) to mount per-agent routes.

No voice endpoints. No Odoo/tool-confirmation flow.
"""

from fastapi import APIRouter, Depends, HTTPException
from fastapi.responses import StreamingResponse
from pydantic import BaseModel

from core.auth import get_current_user
from core.providers import get_ai_provider
from core.providers.credentials import CredentialStore
from .config import AgentConfig
from .context_manager import ContextManager
from .tool_registry import ToolRegistry
from .chat_history.service import ChatHistoryService
from . import ai_service


# ── Request models ────────────────────────────────────────────────────────────

class ChatRequest(BaseModel):
    messages: list[dict]
    conversation_id: str | None = None
    training_mode: bool = False


class ContextWriteRequest(BaseModel):
    content: str


class UpdateTitleRequest(BaseModel):
    title: str


# ── Filename safety ───────────────────────────────────────────────────────────

def _safe_filename(filename: str) -> bool:
    if not filename or not filename.endswith(".md"):
        return False
    if "/" in filename or "\\" in filename or ".." in filename:
        return False
    return True


# ── Factory ───────────────────────────────────────────────────────────────────

def create_agent_router(
    config: AgentConfig,
    ctx_manager: ContextManager,
    chat_service: ChatHistoryService | None = None,
    integration_tool_defs: list[dict] | None = None,
) -> APIRouter:
    """Create a FastAPI router for a single agent.

    The router is intended to be mounted at /api/agents/{agent_id}/ by
    the multi-agent router. It does NOT include the /api/agents prefix itself.

    Args:
        config: Agent configuration
        ctx_manager: Per-agent context file manager
        chat_service: Optional chat history service (enables /conversations endpoints)
        integration_tool_defs: Extra tool definitions from enabled integrations
    """
    router = APIRouter()

    # ── Chat (SSE) ────────────────────────────────────────────────────

    @router.post("/chat")
    async def chat(req: ChatRequest, user=Depends(get_current_user)):
        store = CredentialStore()
        provider = get_ai_provider(
            agent_provider=config.provider_override or None,
            agent_model=config.model_override or None,
            agent_model_tier=config.model_tier,
        )
        if not provider:
            raise HTTPException(status_code=400, detail="No AI provider configured")

        ga = config.google_accounts
        gmail_ids = ga.get("gmail", [])
        calendar_ids = ga.get("calendar", [])
        drive_ids = ga.get("drive", [])
        google_connected = bool(gmail_ids or calendar_ids or drive_ids)

        from integrations.registry import list_google_accounts as _list_ga
        all_ga = _list_ga()
        account_info_map = {
            aid: {"email": a.get("email", ""), "scope_grants": a.get("scope_grants", {}), "connection_status": a.get("connection_status", "ok")}
            for aid, a in all_ga.items()
        }

        registry = ToolRegistry(
            context_dir=config.context_dir,
            google_connected=google_connected,
            gmail_account_ids=gmail_ids,
            calendar_account_ids=calendar_ids,
            drive_account_ids=drive_ids,
            account_info_map=account_info_map,
        )

        # Anthropic API key for smart title generation (haiku)
        _, anthropic_profile = store.get_active_profile(provider_override="anthropic")
        anthropic_api_key = (anthropic_profile or {}).get("api_key", "")

        async def event_generator():
            async for event in ai_service.chat(
                config=config,
                provider=provider,
                registry=registry,
                ctx_manager=ctx_manager,
                messages=req.messages,
                training_mode=req.training_mode,
                conversation_id=req.conversation_id,
                chat_service=chat_service,
                anthropic_api_key=anthropic_api_key,
                integration_tool_defs=integration_tool_defs,
            ):
                yield event

        return StreamingResponse(
            event_generator(),
            media_type="text/event-stream",
            headers={
                "Cache-Control": "no-cache",
                "Connection": "keep-alive",
                "X-Accel-Buffering": "no",
            },
        )

    # ── Onboarding progress ───────────────────────────────────────────

    @router.get("/onboarding/progress")
    def onboarding_progress(user=Depends(get_current_user)):
        content = ctx_manager.read_context("_onboarding-progress.md")
        if not content:
            return {"topics": [], "completed": 0, "total": 0}

        topics = []
        for line in content.splitlines():
            stripped = line.strip()
            if stripped.startswith("- [x]"):
                topics.append({"name": stripped[6:].strip(), "status": "done"})
            elif stripped.startswith("- [~]"):
                topics.append({"name": stripped[6:].strip(), "status": "skipped"})
            elif stripped.startswith("- [ ]"):
                topics.append({"name": stripped[6:].strip(), "status": "pending"})

        done = sum(1 for t in topics if t["status"] == "done")
        return {"topics": topics, "completed": done, "total": len(topics)}

    # ── Context CRUD ──────────────────────────────────────────────────

    @router.get("/context")
    def list_context(user=Depends(get_current_user)):
        return {"files": ctx_manager.list_context_files()}

    @router.get("/context/{filename}")
    def get_context(filename: str, user=Depends(get_current_user)):
        if not _safe_filename(filename):
            raise HTTPException(status_code=400, detail="Invalid filename")
        content = ctx_manager.read_context(filename)
        if not content and not (ctx_manager.data_dir / filename).exists():
            raise HTTPException(status_code=404, detail="File not found")
        return {"filename": filename, "content": content}

    @router.put("/context/{filename}")
    def put_context(filename: str, req: ContextWriteRequest, user=Depends(get_current_user)):
        if not _safe_filename(filename):
            raise HTTPException(status_code=400, detail="Invalid filename")
        ctx_manager.write_context(filename, req.content)
        return {"filename": filename, "ok": True}

    @router.delete("/context/{filename}")
    def delete_context(filename: str, user=Depends(get_current_user)):
        if not _safe_filename(filename):
            raise HTTPException(status_code=400, detail="Invalid filename")
        if not ctx_manager.delete_context(filename):
            raise HTTPException(status_code=404, detail="File not found")
        return {"filename": filename, "deleted": True}

    # ── Conversations (when chat_service provided) ────────────────────

    if chat_service is not None:

        @router.get("/conversations/search")
        def search_conversations(q: str = "", user=Depends(get_current_user)):
            if not q.strip():
                return {"results": []}
            return {"results": chat_service.search_conversations(q.strip())}

        @router.get("/conversations")
        def list_conversations(limit: int = 50, offset: int = 0, user=Depends(get_current_user)):
            return {"conversations": chat_service.list_conversations(limit, offset)}

        @router.post("/conversations")
        def create_conversation(user=Depends(get_current_user)):
            return chat_service.create_conversation()

        @router.get("/conversations/{conv_id}")
        def get_conversation(conv_id: str, user=Depends(get_current_user)):
            result = chat_service.get_conversation(conv_id)
            if not result:
                raise HTTPException(status_code=404, detail="Conversation not found")
            return result

        @router.delete("/conversations/{conv_id}")
        def delete_conversation(conv_id: str, user=Depends(get_current_user)):
            if not chat_service.delete_conversation(conv_id):
                raise HTTPException(status_code=404, detail="Conversation not found")
            return {"deleted": True}

        @router.patch("/conversations/{conv_id}/title")
        def update_conversation_title(
            conv_id: str, req: UpdateTitleRequest, user=Depends(get_current_user)
        ):
            new_title = chat_service.rename_conversation(conv_id, req.title)
            if new_title is None:
                raise HTTPException(status_code=404, detail="Conversation not found or title empty")
            return {"title": new_title}

    return router

