      if (msgs) chat.loadMessages(msgs, newConversationId);
    };
    onboardingCompleteRef.current = () => {
      if (agentId) api<AgentRow>(`/api/agents/${agentId}`).then(a => { setAgent(a); chat.setTrainingMode(false); }).catch(() => { chat.setTrainingMode(false); });
